"""
AtCoder :: M-Solutions Programming Contest 2020 :: Magic 2
https://atcoder.jp/contests/m-solutions2020/tasks/m_solutions2020_b
"""
import sys


def solve(red, green, blue, K):
    """Solve puzzle."""
    # The integer on the green card is strictly greater than the integer on the red card.
    # The integer on the blue card is strictly greater than the integer on the green card.
    for _ in range(K):
        if green > red and blue > green:
            return True

        if red >= green:
            green *= 2
        else:
            blue *= 2

    return green > red and blue > green


def main():
    """Main program."""
    red, green, blue = (int(i) for i in sys.stdin.readline().split())
    K = int(sys.stdin.readline())
    if solve(red, green, blue, K):
        print('Yes')
    else:
        print('No')


if __name__ == '__main__':
    main()

