N, X, Y = map(int, input().split())
dp = [[N] * N for _ in range(N)]
for x in range(N):
  Q = dq([x])
  dp[x][x] = 0
  while len(Q):
    p = Q.popleft()
    if p == X - 1:
      if dp[x][Y - 1] > dp[x][p] + 1:
        dp[x][Y - 1] = min(dp[x][Y - 1], dp[x][p] + 1)
        Q.append(Y - 1)
    if p == Y - 1:
      if dp[x][X - 1] > dp[x][p] + 1:
        dp[x][X - 1] = min(dp[x][X - 1], dp[x][p] + 1)
        Q.append(X - 1)
    if p + 1 < N:
      if dp[x][p + 1] > dp[x][p] + 1:
        dp[x][p + 1] = min(dp[x][p + 1], dp[x][p] + 1)
        Q.append(p + 1)
    if p - 1 >= 0:
      if dp[x][p - 1] > dp[x][p] + 1:
        dp[x][p - 1] = min(dp[x][p - 1], dp[x][p] + 1)
        Q.append(p - 1)
