import numpy

class UnionFind:
    def __init__(self, N):
        self.N = N

        # the parent of all node is itself
        self.parent = list(range(N))

    def root(self, i):
        if self.parent[i] == i:
            return i
        else:
            return self.root(self.parent[i])

    def unite(self, i, j):
        rooti = self.root(i)
        rootj = self.root(j)

        if rooti == rootj:
            return 
        else:
            self.parent[self.root(i)] = rootj

    def same(self, i, j):
        return self.root[i] == self.root[j]

