            if 0 <= nx < W and 0 <= ny < H and maze[ny][nx] == '.':
                pos.append([alter(y, x), alter(ny, nx), 0])
        # warpエッジ
        for w_y in range(-2, 3):
            for w_x in range(-2, 3):
                if w_y == 0 and w_x == 0:
                    continue
                wy = y + w_y
                wx = x + w_x
                if 0 <= wx < W and 0 <= wy < H and maze[wy][wx] == '.':
                    pos.append([alter(y, x), alter(wy, wx), 1])

# 木の生成
def build_tree_dis(N, edge_list):

    G = [[] for i in range(N)]

    for i in range(len(edge_list)):
        a, b, c = edge_list[i]
        G[a].append([b, c])
        # G[b].append([a, c])
        # G[a - 1].append([b - 1, c])
        # G[b - 1].append([a - 1, c])

