    leaves = []
    for i in range(N):
        if len(G[i]) == 1:
            #leaves.append(i)
    """

    return G

edges = build_tree_dis(H * W, pos)

# ダイクストラ
def dij(start, goal, size):
    dist = [float('inf') for i in range(size)]
    dist[start] = 0
    pq = [(0, start)]

    # pqの先頭がgoal行きのものなら最短距離を返す
    while len(pq) > 0:
        d, now = heappop(pq)
        if (d > dist[now]):
            continue
        for i in edges[now]:
            if dist[i[0]] > dist[now] + i[1]:
                dist[i[0]] = dist[now] + i[1]
                heappush(pq, (dist[i[0]], i[0]))
    return dist[goal]

ans = dij(alter(Ch, Cw), alter(Dh, Dw), H * W)
if ans == float('inf'):
    print(-1)
else:
    print(ans)

