@njit((i8, i8, i8[:]), cache=True)
def solve(N, K, A):
    dp = np.zeros(300_001, dtype=int64)
    d = seg.segtree(dp, max)
    for i in range(N):
        x = seg.prod(d, max, A[i] - K, A[i] + K + 1) + 1
        seg.set(d, max, A[i], x)
    return seg.all_prod(d)


