def wfs(y, x, desty, destx, R):
    R[y][x] = 1

    nextL = [[y, x]]

    t = 2
    while len(nextL) != 0:
        for nl in nextL:
            cy, cx = nl
            new_nextL = []
            for dy, dx in zip([-1, 0, 0, 1], [0, 1, -1, 0]):
                    if 0 <= cy + dy < H and 0 <= cx + dx < W and R[cy + dy][cx + dx] == 0:
                        new_nextL.append([cy + dy, cx + dx])
                        R[cy + dy][cx + dx] = t

                        if cy + dy == desty and cx + dx == destx:
                            return R

        t += 1

        nextL = new_nextL


def main():
    global H
    global W

    H, W = li_input()
    A = [li_input() for _ in range(H)]

    ansL = []

    for i in range(H):
        if i % 2 == 0:
            rng_obj = range(0, W-1)
            is_right = True
        else:
            rng_obj = range(W - 1, 0, -1)
            is_right = False

        for j in rng_obj:
            if A[i][j] % 2 == 1:
                if is_right:
                    A[i][j] -= 1
                    A[i][j+1] += 1
                    ansL.append([i, j, i, j + 1])
                else:
                    A[i][j] -= 1
                    A[i][j-1] += 1
                    ansL.append([i, j, i, j - 1])

        if i != H - 1:
            if is_right:
                if A[i][-1] % 2 == 1:
                    A[i][-1] -= 1
                    A[i + 1][-1] += 1
                    ansL.append([i, W - 1, i + 1, W - 1])
            else:
                if A[i][0] % 2 == 1:
                    A[i][0] -= 1
                    A[i + 1][0] += 1
                    ansL.append([i, 0, i + 1, 0])

    print(len(ansL))

    for l in ansL:
        a, b, c, d = l
        print(a+1, b+1, c+1, d+1)




